// SealSeries 封存系列。只有系列创建账户可以封存；封存后不能继续发行，
// 已发行藏品仍可转让，且封存不能撤销。
//
// 封存以保存成功为准：封存状态尚未原子替换原数据就发生写入错误（如数据
// 位置暂时无法写入）时，返回本次实际的保存错误，不返回成功，也不能用失败
// 后重新读取原数据时的错误取代它。即使原数据仍在、却暂时无法读取或解析、
// 状态未能按磁盘重建，同一个仍打开的登记册也必须保持封存前的样子：该系列
// 仍未封存，编号、创建账户与文字元数据不变，仍可按原有条件继续发行，已有
// 藏品的持有人、版本与发行、转让历史原样保留；其他系列此前已经成功保存的
// 封存状态不被恢复为未封存。原数据仍可读取的普通保存失败同样撤销本次变化，
// 不依赖重新读取成功。随后另一次无关操作成功保存也不会把这次未保存的封存
// 夹带落盘。保存条件恢复后创建账户再次封存须重新完成保存，成功返回后才显示
// 已封存，并按现有规则拒绝单件与整批发行；此前发行的藏品仍可转让。
func (r *Registry) SealSeries(seriesID, operator string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if err := r.checkOpen(); err != nil {
		return err
	}
	s, ok := r.state.Series[seriesID]
	if !ok {
		return fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
	}
	if s.CreatorID != operator {
		return fmt.Errorf("%w: 只有创建账户 %s 可以封存系列 %s", ErrForbidden, s.CreatorID, seriesID)
	}
	if s.Sealed {
		return nil // 封存不可撤销，重复封存视为已处于封存态
	}
	// 保存封存前的系列记录：封存以一次保存完成为准。commit 失败且磁盘
	// 暂时不可读、状态未能按磁盘重建时据此显式撤销，否则这次未保存的封存
	// 会留在当前已打开的登记册中（GetSeries 显示已封存、发行被拒绝），重复
	// 封存还会被幂等分支直接返回成功，并被随后另一次成功保存夹带落盘。
	prev := s
	s.Sealed = true
	r.state.Series[seriesID] = s
	if err := r.commit(); err != nil {
		// commit 失败时已尝试按磁盘内容重建状态：重建成功则系列已随旧状态
		// 整体恢复未封存，写回的记录与磁盘一致；磁盘暂时不可读、状态未能重建
		// 时本次封存仍在，显式恢复为封存前记录，藏品持有、版本与历史本就未被
		// 触碰，其他系列的封存状态也保持原样。返回实际写入错误，而非成功或
		// 重新读取时的错误。
		r.state.Series[seriesID] = prev
		return err
	}
	return nil
}

